// One-time seed of the claude-code-web-users-support pack into the EXISTING fleet's
// declarations, naming this fleet's preferences store.
//
// The pack carries what a project can offer people working from Claude Code on the
// WEB, where the session knows who they are — today, reading the current user's
// personal interaction preferences into their session from a repo its config names. New repos get the pack from
// `--init` (it flags `seededByDefault`) and the store from its adoption question;
// this record catches the repos bootstrapped before the pack existed, so today's
// sessions do not silently lose the preferences they had.
//
// It carries the STORE as a literal, which is the one thing a canon record may do
// that shared code may not: a migration record is a dated one-off whose purpose is
// to move a specific fleet off a specific old shape, and it stops shipping once it
// ages out of the vendoring window. Nothing standing is left naming
// `missingbulb/Sheepdog` — the durable path is the pack's adoption question (new
// repos) and the sheepdog pack's fleet-preferences sweep, which reads the store
// from the enforcer repo's own config and so serves any fleet.
//
// SEED, NEVER OVERRIDE (the `declarePacks` op's contract): a repo that already
// declares the pack keeps its entry, and one that already names a store keeps that
// store. Both are decisions this record must not relitigate.
//
// The ORDER this depends on: baselining applies migration notes after it vendors the
// mount, and re-converges the mount when this pass changed the declaration — because
// a declared pack whose code is absent is a blocking `config` error. Both halves land
// in the one transactional commit.
//
// legacyPresent: a member carries a declaration that does not declare the pack at
// all. A repo with no declaration is not a member and is not this record's business;
// a member that declares the pack and deliberately configured it otherwise has
// converged as far as this record is concerned.
export default {
  id: 'claude-code-web-users-support',
  landed: '2026-08-07',
  version: 1,
  summary: 'seed the claude-code-web-users-support pack into existing members, naming the fleet\'s preferences repo',
  declarePacks: [{ id: 'claude-code-web-users-support', config: { repo: 'missingbulb/Sheepdog' } }],
  legacyPresent: async (exists, read) => {
    const raw = await read('.claudinite-checks.json');
    if (raw == null) return false;
    try {
      const { packs } = JSON.parse(raw);
      if (!Array.isArray(packs)) return false;
      return !packs.some((e) => (typeof e === 'string' ? e : e?.id) === 'claude-code-web-users-support');
    } catch {
      return false; // unparsable settings are the world runner's finding, not this record's
    }
  },
};

1	import { join, dirname } from 'node:path';
2	import { fileURLToPath, pathToFileURL } from 'node:url';
3	import { MIGRATION_FILE, migrationDirs, migrationActive, recordName } from '../checks/helpers/active-migrations.mjs';
4	import { MODEL_FAMILIES } from '../scheduler/model-map.mjs';
5	
6	// <corpus>/engine/migrations/ — records are addressed corpus-relative, because they
7	// no longer share one directory with this module: an engine record sits beside it,
8	// a pack's under that pack.
9	const corpusRoot = dirname(dirname(dirname(fileURLToPath(import.meta.url))));
10	
11	// Each migration lives in its own folder under the flow that owns it — an engine
12	// record beside this registry, a pack's under that pack — so a record can carry
13	// assets of its own and each flow can ship exactly its own set. The discovery
14	// surface — the roots, the folder listing, the recency predicate, and
15	// `migrationActive` — lives in the vendored engine lib
16	// (engine/checks/helpers/active-migrations.mjs) because pack CHECKS consult it and packs import
17	// only the engine surface (pack-independence); this registry re-exports it so
18	// canon-side callers keep one import home.
19	export { MIGRATION_FILE, migrationActive, recordName };
20	
21	// Structural discovery, like packs/ and skills/: every
22	// <flow>/migrations/<landed-date>-<slug>/migration.mjs is a spec. ALL records
23	// present load — the apply/backfill path is unconditional, and FETCHING decides
24	// relevance: a vendored consumer mount carries only the recent records
25	// (vendoring's recency window), while a dormant project baselining out of a
26	// fresh canon clone sees every record ever landed and applies what it needs.
27	// Each object carries its `dir` — the record's CORPUS-RELATIVE path, which both
28	// names the record and says which flow owns it.
29	export async function loadMigrations() {
30	  const out = [];
31	  for (const d of migrationDirs()) {
32	    const spec = (await import(pathToFileURL(join(corpusRoot, d, MIGRATION_FILE)).href)).default;
33	    out.push({ dir: d, ...spec });
34	  }
35	  return out;
36	}
37	
38	// Read side — "prefer Y, fall back to X": the ordered list of acceptable paths
39	// for a canonical target (canonical first, then its legacy aliases). A tolerance
40	// point consults this instead of hardcoding its own LEGACY_* constant, so a
41	// rename is declared once here and every reader picks it up. Unknown targets
42	// resolve to just themselves.
43	export function resolvePath(migrations, canonical) {
44	  for (const m of migrations) {
45	    for (const a of m.aliases ?? []) {
46	      if (a.canonical === canonical) return [a.canonical, ...(a.legacy ?? [])];
47	    }
48	  }
49	  return [canonical];
50	}
51	
52	// Write side — "and rename X -> Y": for each alias whose legacy path still
53	// exists and whose canonical does not, move legacy -> canonical. `exists` and
54	// `move` are injected so the same logic drives a local checkout (sync fs) or a
55	// future API applier (async). Idempotent — a no-op once the rename is done.
56	export async function applyFileAliases(migration, { exists, move }) {
57	  const moved = [];
58	  for (const a of migration.aliases ?? []) {
59	    for (const legacy of a.legacy ?? []) {
60	      if ((await exists(legacy)) && !(await exists(a.canonical))) {
61	        await move(legacy, a.canonical);
62	        moved.push(`${legacy} -> ${a.canonical}`);
63	      }
64	    }
65	  }
66	  return moved;
67	}
68	
69	// Write side — "vendor these pack templates into the repo": for each declared
70	// materialization {template, dest}, copy the canon template to its destination
71	// when the dest is missing or has drifted from the template (idempotent; a
72	// hand-edited copy self-heals on the next pass). `readTemplate` reads from the
73	// canon (the pack tree / mounted .claudinite), `read`/`write` act on the consumer
74	// repo — the source and destination roots differ in a consumer, so they are
75	// distinct injected readers. Gated by the migration's `appliesTo` so it only
76	// touches repos that ship the pipeline (never the canon repo itself).
77	// A materialization whose dest is a WORKFLOW FILE can only be written by a caller that
78	// can get it delivered. The nightly converge pushes with the Action's GITHUB_TOKEN, which
79	// GitHub never lets write under `.github/workflows/`, and the refusal rejects the whole
80	// ref — so writing one into a tree that is about to be pushed by such a caller does not
81	// deliver a workflow, it fails the entire converge and everything else riding it.
82	//
83	// The capable caller announces itself with this variable. The baselining worker sets it
84	// when it can WITHHOLD those paths from its commit and hand them to the agent stage;
85	// anything else — an older vendored worker, a hand-run `node migrations/apply.mjs`, CI —
86	// leaves it unset and the workflow materialization is skipped with a note.
87	//
88	// An ENV HANDSHAKE rather than a probe of the repo on disk, because what matters is what
89	// the RUNNING process can do and the disk cannot answer that: the vendor step earlier in
90	// the same cycle replaces the on-disk worker with the new one while the old code is still
91	// executing.
92	export const WITHHOLD_CAPABLE_ENV = 'CLAUDINITE_CAN_WITHHOLD_WORKFLOWS';
93	const WORKFLOW_DEST = '.github/workflows/';
94	export const callerCanDeliverWorkflows = (env = process.env) => env[WITHHOLD_CAPABLE_ENV] === '1';
95	
96	export async function applyMaterializations(migration, { readTemplate, read, write, env = process.env }) {
97	  if (!migration.materialize?.length) return [];
98	  if (migration.appliesTo && !(await migration.appliesTo(read))) return [];
99	  const done = [];
100	  for (const { template, dest } of migration.materialize) {
101	    const content = await readTemplate(template);
102	    if (content == null) continue; // template missing (partial mount) — skip, never clobber with nothing
103	    if ((await read(dest)) === content) continue; // already vendored, unchanged
104	    if (dest.startsWith(WORKFLOW_DEST) && !callerCanDeliverWorkflows(env)) {
105	      // Reported rather than silent — a silent skip reads as "already current". A caller
106	      // that can withhold writes it on a later cycle.
107	      done.push(`SKIPPED ${dest} (workflow file; this caller cannot deliver one)`);
108	      continue;
109	    }
110	    await write(dest, content);
111	    done.push(`${dest} <- ${template}`);
112	  }
113	  return done;
114	}
115	
116	// Write side — "rewrite these refs in place": for each declared file, apply its
117	// replacements (only those still matching), writing back when anything changed.
118	// Idempotent — a no-op once nothing matches. Preserves the rest of the file, so
119	// per-repo tweaks the template can't carry (e.g. an uncommented build_env block)
120	// survive. Same `appliesTo` gate.
121	//
122	// A replacement is either LITERAL (`{ from, to }`) or a PATTERN
123	// (`{ pattern: /…/g, to }`) — the regex-first shape engine migrations are meant to
124	// take (DESIGN §2.3), for the changes where no literal is common across repos.
125	// The pattern must be global, because every replacement here means replace-ALL:
126	// a non-global regex would silently rewrite only the first occurrence and leave a
127	// half-migrated file that reads as migrated.
128	export async function applyRewrites(migration, { read, write }) {
129	  if (!migration.rewrite?.length) return [];
130	  if (migration.appliesTo && !(await migration.appliesTo(read))) return [];
131	  const done = [];
132	  for (const { file, replace } of migration.rewrite) {
133	    const text = await read(file);
134	    if (text == null) continue;
135	    let next = text;
136	    for (const r of replace ?? []) {
137	      if (r.pattern !== undefined) {
138	        if (!(r.pattern instanceof RegExp) || !r.pattern.global) {
139	          throw new Error(`migration ${migration.id}: rewrite pattern for ${file} must be a global RegExp — a non-global one rewrites only the first match`);
140	        }
141	        next = next.replace(r.pattern, r.to);
142	      } else {
143	        next = next.split(r.from).join(r.to);
144	      }
145	    }
146	    if (next !== text) { await write(file, next); done.push(file); }
147	  }
148	  return done;
149	}
150	
151	// The declaration a pack-seeding op writes into. Fixed, not a parameter: this op
152	// declares PACKS, and a repo's declaration lives in exactly one file. A `file` knob
153	// would quietly make it a general JSON editor, which is a much larger thing to own.
154	export const DECLARATION = '.claudinite-checks.json';
155	
156	// Write side — "every member should now declare this pack": for each declared
157	// `{ id, config }`, add that pack to the member's `packs` when it is absent, and
158	// fill in a `config` the entry does not already carry. The op the other three could
159	// not express — `materialize` writes a whole template (it would clobber a per-repo
160	// declaration) and `rewrite` replaces literal text (declarations share no literal
161	// across repos) — and the shape a fleet-wide capability change actually has: a pack
162	// every member should run, whose parameters the canon knows and the member cannot
163	// derive.
164	//
165	// SEEDING, NEVER OVERRIDING. A pack the repo already declares keeps its entry, and a
166	// config it already carries is left exactly as it is: both are that repo's decisions,
167	// and a migration that reasserted them would fight the project every night. That
168	// makes the op idempotent by construction — a no-op once the entry is there.
169	//
170	// ORDER MATTERS AROUND IT. Declaring a pack whose code is not in the member's mount
171	// is a blocking `config` error there, so the caller must re-converge the mount after
172	// applying (baselining does; see its worker). This module only writes the file.
173	//
174	// It round-trips the file through JSON rather than editing settings as text, so the
175	// result is canonical 2-space settings with a trailing newline (what `--init` writes,
176	// and what every fleet declaration already is). Malformed JSON is left alone: the
177	// world runner reports it as the settings error it is, and a migration is not the
178	// place to guess at a repair. Same `appliesTo` gate as the other write ops.
179	export async function applyPackDeclarations(migration, { read, write }) {
180	  if (!migration.declarePacks?.length) return [];
181	  if (migration.appliesTo && !(await migration.appliesTo(read))) return [];
182	  const raw = await read(DECLARATION);
183	  if (raw == null) return [];                       // not a member — nothing to declare into
184	  let config;
185	  try { config = JSON.parse(raw); } catch { return []; }
186	  if (config === null || typeof config !== 'object' || Array.isArray(config)) return [];
187	  const packs = Array.isArray(config.packs) ? [...config.packs] : [];
188	  const idOf = (e) => (typeof e === 'string' ? e : e?.id);
189	  const done = [];
190	  for (const { id, config: packConfig } of migration.declarePacks) {
191	    const at = packs.findIndex((e) => idOf(e) === id);
192	    if (at === -1) {
193	      packs.push(packConfig ? { id, config: packConfig } : id);
194	      done.push(`${DECLARATION}: declared ${id}`);
195	      continue;
196	    }
197	    // Declared already: the only thing still owed is a config it never got.
198	    if (!packConfig) continue;
199	    const prior = typeof packs[at] === 'string' ? { id } : packs[at];
200	    if (prior.config) continue;                     // the repo's own parameters — untouched
201	    packs[at] = { ...prior, id, config: packConfig };
202	    done.push(`${DECLARATION}: configured ${id}`);
203	  }
204	  if (done.length) await write(DECLARATION, `${JSON.stringify({ ...config, packs }, null, 2)}\n`);
205	  return done;
206	}
207	
208	// Write side — "normalize this repo's local-pack declarations": rewrite every
209	// declared local pack to the canonical `local/<id>` token, from the bare id or the
210	// earlier `local_packs/<id>` form.
211	//
212	// A NAMED CODEMOD rather than a `rewrite`, because the decision needs the repo's
213	// own disk. `local_packs/<id>` → `local/<id>` is a pure pattern, but a BARE id is
214	// only a local pack if that repo has one by that name — and a bare id that names a
215	// canon pack must not be touched. No regex can tell those apart, so the record
216	// declares `normalizeLocalDeclarations: true` and the deterministic code ships with
217	// the engine (DESIGN §2.3's "rarely code"). It is one op with one meaning, not a
218	// general escape hatch for arbitrary code in a record.
219	//
220	// SEEDS NOTHING AND DROPS NOTHING: entry objects keep their config, answers and
221	// order; only the id token changes. Idempotent — a repo already on `local/` is a
222	// no-op — and it patches the parsed declaration back through JSON.stringify with
223	// the same 2-space shape every other declaration writer here uses.
224	export async function applyLocalDeclarationNormalization(migration, { read, write, exists }) {
225	  if (!migration.normalizeLocalDeclarations) return [];
226	  if (migration.appliesTo && !(await migration.appliesTo(read))) return [];
227	  const raw = await read(DECLARATION);
228	  if (raw == null) return [];
229	  let config;
230	  try { config = JSON.parse(raw); } catch { return []; }
231	  if (config === null || typeof config !== 'object' || Array.isArray(config)) return [];
232	  if (!Array.isArray(config.packs)) return [];
233	
234	  const done = [];
235	  const packs = [];
236	  for (const entry of config.packs) {
237	    const id = typeof entry === 'string' ? entry : entry?.id;
238	    if (typeof id !== 'string' || id.startsWith(LOCAL_DECL)) { packs.push(entry); continue; }
239	    let bare = id.startsWith(LEGACY_LOCAL_DECL) ? id.slice(LEGACY_LOCAL_DECL.length) : null;
240	    if (bare === null) {
241	      // A bare id: local only if this repo actually carries that pack. Both mount
242	      // shapes are checked, because a repo mid-relocation may hold either.
243	      const isLocal = (await exists(`.claudinite/local/packs/${id}/pack.mjs`))
244	        || (await exists(`.claudinite/local_packs/${id}/pack.mjs`));
245	      if (!isLocal) { packs.push(entry); continue; }
246	      bare = id;
247	    }
248	    const token = `${LOCAL_DECL}${bare}`;
249	    packs.push(typeof entry === 'string' ? token : { ...entry, id: token });
250	    done.push(`${DECLARATION}: ${id} -> ${token}`);
251	  }
252	  if (done.length) await write(DECLARATION, `${JSON.stringify({ ...config, packs }, null, 2)}\n`);
253	  return done;
254	}
255	
256	// The declaration tokens this op normalizes to and from. Stated here rather than
257	// imported from the pack registry: this module is the write side a consumer runs
258	// out of its own mount, and the two prefixes are the whole of what it needs.
259	const LOCAL_DECL = 'local/';
260	const LEGACY_LOCAL_DECL = 'local_packs/';
261	
262	// EVERY write op a record can carry, in the order a run applies them, over one
263	// injected io. Both callers — the standalone applier and the engine update flow —
264	// go through this, so an op added to the vocabulary cannot reach one and miss the
265	// other: that omission is silent (the record simply does nothing on that path) and
266	// is exactly what a member would never notice.
267	export async function applyMigration(migration, io) {
268	  const applied = [];
269	  applied.push(...(await applyFileAliases(migration, io)));
270	  applied.push(...(await applyMaterializations(migration, io)));
271	  applied.push(...(await applyRewrites(migration, io)));
272	  applied.push(...(await applyPackDeclarations(migration, io)));
273	  applied.push(...(await applyLocalDeclarationNormalization(migration, io)));
274	  return applied;
275	}
276	
277	// A migration record MAY carry a machine-readable AGENTIC note (task-prework
278	// DESIGN §7, the primitive absorbed from #405): member-side adaptation that no
279	// script can do — adapting consumer-authored `local/packs/` content to a changed
280	// engine contract. Shape: `agentic: { model, instructions }`, model a non-`none`
281	// family. baselining's prework reads this to decide whether a pending note
282	// needs the agent STAGE (and must therefore hold the stamp) rather than converging
283	// in code. Returns the validated note, or null when the record carries none;
284	// throws on a malformed note so a typo fails loudly instead of silently skipping
285	// agentic work (the #405 correctness risk).
286	export function migrationAgentic(m) {
287	  const a = m.agentic;
288	  if (a === undefined || a === null) return null;
289	  // NO AGENTIC WORK ON AN ENGINE MIGRATION, EVER (DESIGN §5, owner decision 3). The
290	  // engine update flow has no agentic stage and no lane to add one, so a note on an
291	  // engine record is not work that gets done later — it is a record that stops the
292	  // flow for every repo whose gap contains it. Rejected here, at the registry, so it
293	  // cannot be written in the first place; a pack record is where such work belongs,
294	  // as its update's apply stage.
295	  //
296	  // Judged by WHERE THE RECORD LIVES (`dir`, corpus-relative), the same structural
297	  // classifier everything else in this scheme uses. A spec with no `dir` is a caller
298	  // testing the shape rather than a discovered record, and is left alone.
299	  if (typeof m.dir === 'string' && m.dir.startsWith('engine/')) {
300	    throw new Error(`migration ${m.id}: an ENGINE migration may not carry an "agentic" note — `
301	      + 'the engine flow cannot run one (DESIGN §5). Move the work to the owning pack\'s apply stage.');
302	  }
303	  if (typeof a !== 'object' || Array.isArray(a)) {
304	    throw new Error(`migration ${m.id}: "agentic" must be an object { model, instructions }`);
305	  }
306	  if (!MODEL_FAMILIES.includes(a.model) || a.model === 'none') {
307	    throw new Error(`migration ${m.id}: agentic.model must be a non-"none" model family (${MODEL_FAMILIES.filter((f) => f !== 'none').join(', ')})`);
308	  }
309	  if (typeof a.instructions !== 'string' || a.instructions.trim() === '') {
310	    throw new Error(`migration ${m.id}: agentic.instructions must be a non-empty string`);
311	  }
312	  return { model: a.model, instructions: a.instructions };
313	}
314	
315	// The records that carry a valid agentic note — the pending set baselining must
316	// escalate to an agent rather than apply in code. Stamp-date filtering (which
317	// notes still apply) is the caller's; this is the agentic gate over that set.
318	export function agenticMigrations(migrations) {
319	  return migrations.filter((m) => migrationAgentic(m) !== null);
320	}
321	
322

1	// baselining worker — the DETERMINISTIC self-refresh, as prework
2	// (task-prework DESIGN §7, E4). This is `agent_model: 'sonnet'` with
3	// `prework: 'node worker.mjs'`, so the scheduler runs THIS FILE as a
4	// subprocess (cwd = this task dir) bounded by `prework_timeout`,
5	// BEFORE any agent. It absorbs everything about the nightly refresh that is
6	// dependency-free code — so most nights are AGENTLESS and quiet, and an agent is
7	// requested only when real judgment is left (owner decision, 2026-07-23):
8	//
9	//   agent requested  ⇔  a pending AGENTIC migration note exists
10	//                    OR  the converge changed things AND check_the_world is not green.
11	//   no change, or changed-but-green with no agentic note  →  agentless night.
12	//
13	// What it does, Action-side, over the one sanctioned non-MCP surface (the Action
14	// GITHUB_TOKEN in env) and a direct PUBLIC canon fetch (owner §10: canon is
15	// public — no token, no tarball channel):
16	//   1. shallow-clone canon at its head sha (then drop .git → a rootless tree, so
17	//      apply-vendor-set skips the ancestry guards that a shallow clone can't
18	//      satisfy — it is head by construction);
19	//   2. run the CLONED canon's vendoring/apply-vendor-set.mjs to converge
20	//      .claudinite/shared/ and stamp it (compute+apply, one snapshot);
21	//   3. run the cloned converge-wiring.mjs (scheduler workflow + hashed cron + the
22	//      tasks' declared required_secrets, settings hooks, retired-import removal),
23	//      and ask the owner for any declared secret the repo hasn't configured;
24	//   4. apply the MECHANICAL migration notes (aliases/materialize/rewrite/declarePacks)
25	//      via the cloned engine/migrations/apply.mjs — idempotent — and re-converge the mount
26	//      when that changed the DECLARATION, since a newly declared pack's content was
27	//      not in the set the vendor pass computed a moment earlier;
28	//   5. detect pending AGENTIC notes (registry.mjs `agenticMigrations`, gated on
29	//      the prior stamp day, same-day inclusive #330) and, if any, HOLD the stamp
30	//      at the day before the earliest one so the agent still sees the note (the
31	//      stamp/agentic coupling rule);
32	//   6. deliver the converge as ONE commit on the per-cycle maintenance branch via
33	//      NATIVE git (dispose of the family's open PR — merge it if its own runs
34	//      verified it, else close it — then cut a fresh dated branch and open the
35	//      PR), arming auto-merge per the
36	//      member's `maintenance.delivery` and DISPATCHING the repo's PR CI on the
37	//      branch — the GITHUB_TOKEN push emits no pull_request run of its own
38	//      (#565), so the checks the arm waits on must be started explicitly;
39	//   7. request the agent (write CLAUDINITE_REQUEST_AGENT) only when judgment is
40	//      left — the scheduler files `ready-for-agent` iff this file appears (§3,
41	//      conditional handoff). NO code→agent data channel: the file is a pure
42	//      control signal; the agent discovers its work by reading the repo (the
43	//      pushed branch, the pending note).
44	//
45	// Imports: node builtins, plus the vendored ENGINE SURFACE — the one import the
46	// pack-independence barrier sanctions. The delivery/landing nuances live in
47	// `engine/scheduler/land-pr.mjs` (one home for every PR-delivering task; its
48	// helpers grew here and moved out), vendored beside this worker and loaded at
49	// process start — so the mid-run mount overwrite (apply-vendor-set rewriting the
50	// tree this process is executing from) can never mix an old worker with new
51	// landing logic. The vendoring/migrations machinery stays canon-internal
52	// (vendoring/ is never vendored, #385), so the worker INVOKES the
53	// freshly-fetched canon's scripts as subprocesses and DYNAMIC-imports its
54	// registry from the temp clone path — never a static import of that code.
