116	// The paths this stage is STRUCTURALLY UNABLE to deliver. deliver() pushes with the
117	// Action's GITHUB_TOKEN, and GitHub refuses to let that token create or update anything
118	// under `.github/workflows/` — there is no `permissions:` key that grants it. The refusal
119	// is remote-side and rejects the WHOLE ref, so a workflow file left in the commit fails
120	// the entire push, taking the mount convergence, the wiring and every other note with it.
121	//
122	// So the converge withholds exactly these paths and hands them to the AGENT stage, whose
123	// writes go through the session's MCP GitHub tools — a credential that does hold the
124	// `workflows` permission. The agent re-runs the same mechanical apply in its own checkout
125	// to produce them.
126	//
127	// It covers `convergeWiring`'s scheduler workflow as much as any pack-owned one.
128	export const UNPUSHABLE_PREFIX = '.github/workflows/';
129	export function withheldWorkflowPaths(changedPaths) {
130	  return (changedPaths ?? []).filter((p) => p.startsWith(UNPUSHABLE_PREFIX));
131	}
