184	// The same decision as a bit, for the callers that only need the verdict. Derived
185	// rather than reimplemented — two copies of a four-branch precedence is exactly the
186	// drift the corpus forbids.
187	export function shouldRequestAgent(signals) {
188	  return escalation(signals) !== null;
189	}
