210	async function gh(token, path, { method = 'GET', body } = {}) {
211	  const res = await fetch(`${API}${path}`, {
212	    method,
213	    headers: {
214	      authorization: `Bearer ${token}`,
215	      accept: 'application/vnd.github+json',
216	      'x-github-api-version': '2022-11-28',
217	      ...(body ? { 'content-type': 'application/json' } : {}),
218	    },
219	    body: body ? JSON.stringify(body) : undefined,
220	  });
221	  let json = null;
222	  try { json = await res.json(); } catch { /* empty body */ }
223	  return { status: res.status, json };
224	}
