226	// The outcome of running one gate script, from what `node()` threw (or didn't).
227	// PURE, so the four shapes are testable without a repo on disk.
228	//
229	// `catch { return false }` was the whole of this before, and it collapsed four
230	// different events into one indistinguishable bit: findings, a crash, a signal kill,
231	// and a script that isn't there. `node()` already pipes stdout/stderr, so the
232	// findings were in the thrown error's `.stdout` all along and the bare catch dropped
233	// them — leaving the escalation they caused unexplainable after the fact
234	// (EdFringeAllocator#82: a run that escalated on a check which passes everywhere it
235	// can be re-run, with no record of what it saw).
236	//
237	// `crashed` is the distinction that matters most: a non-zero EXIT is a verdict about
238	// the repo's content, while a null status — signal kill, spawn failure — means no
239	// verdict was produced at all. Both still escalate to the agent (a gate that cannot
240	// answer is not permission to proceed), but they are no longer the same sentence.
241	export function gateOutcome(error) {
242	  if (!error) return { ok: true, ran: true, crashed: false, status: 0, output: '' };
243	  const status = Number.isInteger(error.status) ? error.status : null;
244	  const output = `${error.stdout ?? ''}${error.stderr ?? ''}`.trim();
245	  return { ok: false, ran: true, crashed: status === null, status, output };
246	}
247	
248	// A gate that isn't vendored at all is nothing to run — not a failure. Distinct from
249	// `crashed`, which is a gate that exists and could not answer.
250	export const GATE_ABSENT = Object.freeze({ ok: true, ran: false, crashed: false, status: null, output: '' });
251	
252	// Run check_the_world against the converged repo. Green means it exited clean (no
253	// blocking findings); anything else is judgment left, with the reason attached.
254	function runCheckTheWorld(root) {
255	  const cw = join(root, '.claudinite/shared/engine/checks/check_the_world.mjs');
256	  if (!existsSync(cw)) return GATE_ABSENT; // no vendored checks to gate on
257	  try { node([cw], { CLAUDE_PROJECT_DIR: root }, { cwd: root }); return gateOutcome(null); }
258	  catch (e) { return gateOutcome(e); }
259	}
