284	// mount that predates it) is not a failure, it is nothing to run.
285	function runSelfTest(root) {
286	  const st = join(root, '.claudinite/shared/engine/selftest.mjs');
287	  if (!existsSync(st)) return GATE_ABSENT;
288	  try { node([st, '--strict'], { CLAUDE_PROJECT_DIR: root }, { cwd: root }); return gateOutcome(null); }
289	  catch (e) { return gateOutcome(e); }
290	}
